using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;
class AchievementChecks{[STAThread]static void Main(){Application.EnableVisualStyles();using(var g=new Game()){g.Show();using(var timer=new Timer{Interval=200}){timer.Tick+=(s,e)=>{var d=Application.OpenForms.OfType<GuildWordDialog>().FirstOrDefault(x=>x.Text=="冒险成就");if(d==null)return;timer.Stop();var body=d.Controls.OfType<Panel>().Single();var cards=body.Controls.OfType<AchievementPlaque>().ToArray();if(cards.Length!=5||body.AutoScroll||cards.Any(c=>c.Bottom>body.Height-36))throw new Exception("Achievement layout");using(var b=new Bitmap(d.Width,d.Height)){d.DrawToBitmap(b,d.ClientRectangle);b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"achievements-redesign.png"));}d.Close();};timer.Start();typeof(Game).GetMethod("ShowAchievements",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(g,null);}if((string)typeof(Game).GetField("page",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(g)!="home")throw new Exception("Changed underlying page");g.Close();}Console.WriteLine("PASS five achievement cards, no scrollbar, modal close preserves home.");}}
